    MuscleRule("""(?<!\p{L})рук[иу]?(?!\p{L})|\barms?\b""", setOf(RegexOption.IGNORE_CASE), listOf("biceps", "triceps"), emptyList()),
    MuscleRule("""\bcore\b|(?<!\p{L})кор(?!\p{L})""", setOf(RegexOption.IGNORE_CASE), listOf("abs", "obliques"), emptyList()),
